function changePlan(){planVariant=(planVariant+1)%12;localStorage.setItem('gtai_plan_variant',String(planVariant));renderPlan();const b=document.querySelector('#recommend button[onclick="changePlan()"]');if(b)b.textContent=lang==='uk'?'✓ План оновлено — ще варіант':'✓ Plan updated — another option';}
function renderPlan(){if(!profile)return;const plan=buildPlan();$('planTitle').textContent=plan.title;$('planDesc').textContent=`${goalText()} · ${profile.days} ${t('daysLabel')} · ${profile.duration} ${t('minLabel')}`;$('planStats').innerHTML=`<div class="stat"><strong>${profile.days}</strong><small>${t('daysLabel')}</small></div><div class="stat"><strong>${profile.duration}</strong><small>${t('minLabel')}</small></div><div class="stat"><strong>${profile.level==='beginner'?'1':profile.level==='some'?'2':'3'}</strong><small>${t('levelLabel')}</small></div>`;$('planWhy').textContent=t(profile.level==='beginner'?'whyBeginner':profile.level==='some'?'whySome':'whyExperienced');$('planDays').innerHTML=plan.days.map((d,i)=>`<div class="card"><div class="row"><h3>${esc(d.title)}</h3><span class="pill">${profile.duration} хв</span></div><p class="hint">${i===2&&profile.days===5?'День помірної активності — не кожне заняття має бути інтенсивним.':'Виконуй рухи контрольовано, залишай запас сил і відпочивай між підходами.'}</p>${d.items.map(e=>`<div class="exercise"><div class="details"><b>${esc(e[0])}</b><small>${esc(e[1])}</small></div></div>`).join('')}</div>`).join('')}
function startWorkout(name){if(!profile){showPage('setup');return}currentWorkout=name;let place=profile.place;let plan=buildPlan();currentExercises=name==='Mobility'?translations[lang].mobilityExercises.map((x,i)=>[x,i===4?'gentle':'2 × 8–10']):name==='Recommended workout'?plan.days[0].items:(exercises[place]||exercises.home);if(name==='Full Body')currentExercises=(exercises[place]||exercises.home);$('sessionTitle').textContent=name==='Mobility'?t('mobilityWorkout'):name==='Recommended workout'?t('recommended'):name;$('exerciseList').innerHTML=currentExercises.map((e,i)=>`<div class="exercise"><input type="checkbox" id="ex${i}"><div class="details"><b>${esc(e[0])}</b><small>${esc(e[1])}</small></div></div>`).join('');setTimer(90);showPage('session')}
function renderCustomSessionText(){}
function setTimer(n){timer=n;updateClock();stopTimer()};function updateClock(){$('clock').textContent=String(Math.floor(timer/60)).padStart(2,'0')+':'+String(timer%60).padStart(2,'0')};function toggleTimer(){if(running){stopTimer();return}running=true;$('timerButton').textContent=t('pauseTimer');timerInterval=setInterval(()=>{timer--;updateClock();if(timer<=0){stopTimer();if(navigator.vibrate)navigator.vibrate([200,100,200]);alert(lang==='uk'?'Час відпочинку завершено!':'Rest time is over!')}},1000)}function stopTimer(){clearInterval(timerInterval);timerInterval=null;running=false;if($('timerButton'))$('timerButton').textContent=t('startTimer')}
function finishWorkout(){const done=document.querySelectorAll('#exerciseList input:checked').length;if(!done&&!confirm(lang==='uk'?'Не позначено вправ. Зберегти тренування?':'No exercises checked. Save workout anyway?'))return;history.unshift({name:currentWorkout,date:new Date().toISOString(),done,minutes:profile.duration});localStorage.setItem('gtai_history',JSON.stringify(history));stopTimer();alert(t('finished'));renderHome();showPage('home')}
function renderHistory(){$('historyList').className=history.length?'card':'card empty';$('historyList').innerHTML=history.length?history.map(h=>`<div class="exercise"><div class="details"><b>${esc(h.name)}</b><small>${new Date(h.date).toLocaleString(lang==='uk'?'uk-UA':'en-US')}</small></div><span class="pill">${h.done} ${t('done')}</span></div>`).join(''):t('noHistory')}
function logoutProfile(){if(!confirm('У цій демоверсії немає справжніх окремих онлайн-акаунтів. Вихід видалить профіль та історію тренувань, збережені в цьому браузері. Продовжити?'))return;localStorage.removeItem('gtai_profile');localStorage.removeItem('gtai_history');localStorage.removeItem('gtai_plan_variant');profile=null;history=[];planVariant=0;showPage('setup')}function clearHistory(){if(confirm(t('clearConfirm'))){history=[];localStorage.setItem('gtai_history','[]');renderHistory();renderHome()}}function resetAll(){if(confirm(t('resetConfirm'))){localStorage.removeItem('gtai_profile');localStorage.removeItem('gtai_history');localStorage.removeItem('gtai_lang');profile=null;history=[];showPage('setup')}}function exportData(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({profile,history},null,2)],{type:'application/json'}));a.download='gym-trainer-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);alert(t('exported'))}
function addBubble(text,who){const d=document.createElement('div');d.className='bubble '+who;d.textContent=text;$('chatlog').appendChild(d);d.scrollIntoView({block:'nearest',behavior:'smooth'})}function quickAsk(type){const q={plan:t('askPlan'),recovery:t('askRecovery'),technique:t('askTechnique')}[type];$('chatInput').value=q;sendChat()}function sendChat(){const input=$('chatInput'),q=input.value.trim();if(!q)return;addBubble(q,'user');input.value='';const low=q.toLowerCase();let reply;if(/plan|програм|тренуван|workout|routine/.test(low))reply=t('askPlanReply')+'\n\n'+(profile?buildPlan().title:t('saveFirst'));else if(/віднов|recovery|rest|сон|sleep|втом/.test(low))reply=t('askRecoveryReply');else if(/технік|technique|squat|присід|push.?up|віджим|deadlift/.test(low))reply=t('askTechniqueReply');else reply=t('defaultReply');setTimeout(()=>addBubble(reply,'bot'),120)}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
