if (typeof libraryExercises !== 'undefined') {
 const seen = new Set(libraryExercises.map(e=>String(e.name||'').toLowerCase()));
 GT_EXTRA_TRICEPS_EXERCISES.forEach(e=>{if(!seen.has(e.name.toLowerCase()))libraryExercises.push(e)});
}
function normalizeExerciseQuery(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('uk').trim()}function exerciseSearchText(e){return [e.name,e.en,e.muscles,e.category,...(e.aliases||[])].filter(Boolean).join(' ')}let libraryFilter='Усі';function setLibraryFilter(filter,button){libraryFilter=filter;document.querySelectorAll('#libraryFilters .chip').forEach(b=>b.classList.remove('selected'));button.classList.add('selected');renderLibrary()}function renderLibrary(){const root=$('libraryList');if(!root)return;const q=normalizeExerciseQuery($('exerciseSearch')?.value||'');const items=libraryExercises.filter(e=>(libraryFilter==='Усі'||e.category===libraryFilter)&&normalizeExerciseQuery(exerciseSearchText(e)).includes(q));$('exerciseCount').textContent=items.length+' вправ';root.innerHTML=items.map((e,i)=>`<article class="card exercise-card"><div class="tag">${esc(e.category.toUpperCase())}</div><h3>${esc(e.name)}</h3><p><b>Основні м’язи:</b> ${esc(e.muscles)}</p><p><b>Як виконувати:</b> ${esc(e.how)}</p><p class="hint"><b>Поширені помилки:</b> ${esc(e.mistakes)}</p>${e.video?`<details class="video-details"><summary class="btn secondary">▶ Переглянути відеофайл</summary><video controls preload="none" playsinline style="width:100%;max-height:320px;border-radius:12px;margin-top:10px;background:#0a080b" src="${e.video}"></video><p class="hint">${esc(e.videoTitle)} · ${esc(e.credit)} · <a href="${e.video}" target="_blank" rel="noopener">Відкрити / завантажити файл</a></p></details>`:'<p class="hint">Відео для цієї вправи ще не додано.</p>'}</article>`).join('')||'<div class="card empty">Нічого не знайдено.</div>'}
function boot(){applyLang();if(profile&&profile.email){if(!profile.goal)profile.goal='maintain';if(!profile.duration||profile.duration>120)profile.duration=30;showPage('home');fillEditProfile()}else showPage('setup')}boot();
